// src/data/internationalServices/internationalServiceRegistry.ts
var INTERNATIONAL_SERVICES = [...CHARMI_INTERNATIONAL_SERVICES, ...ZALAK_INTERNATIONAL_SERVICES];
var serviceBySlug = new Map(INTERNATIONAL_SERVICES.map((s) => [s.slug, s]));
function internationalServicePath(slug) {
  return publicPathname(`${INTERNATIONAL_CONSULTATION_BASE}/${slug}`);
}
function internationalDoctorHubPath(hub) {
  return publicPathname(`${INTERNATIONAL_CONSULTATION_BASE}/${hub.pathSegment}`);
}
function getInternationalService(slug) {
  return serviceBySlug.get(slug);
}
function getInternationalDoctorHub(pathSegment) {
  return INTERNATIONAL_DOCTOR_HUBS.find((h) => h.pathSegment === pathSegment);
}
function internationalServiceSitemapPaths() {
  const paths = [
    publicPathname(INTERNATIONAL_HUB.path),
    ...INTERNATIONAL_DOCTOR_HUBS.map((h) => internationalDoctorHubPath(h)),
    ...INTERNATIONAL_SERVICES.map((s) => internationalServicePath(s.slug)),
  ];
  return paths.sort((a, b) => a.localeCompare(b));
}

// src/data/internationalServices/internationalConsultationSitemapPaths.ts
function internationalConsultationSitemapPaths() {
  return internationalServiceSitemapPaths();
}

