function ensureHttpsSiteOrigin(siteUrl) {
  const s = siteUrl.trim().replace(/\/$/, "");
  if (!s) return s;
  try {
    const u = new URL(s.startsWith("http") ? s : `https://${s}`);
    if (u.hostname === "localhost" || u.hostname === "127.0.0.1") {
      return s;
    }
    if (u.protocol === "http:") {
      u.protocol = "https:";
    }
    const path3 = u.pathname === "/" ? "" : u.pathname.replace(/\/$/, "");
    return `${u.protocol}//${u.host}${path3}`;
  } catch {
    return s;
  }
}

